{"rob": "robolang 1.3;

task move_box(robot r, object box, location src, location dst, region cell) {
    goal { object_at box dst; }
    plan {
        wait until region_clear cell timeout 30 s;
        move r to src;
        grasp r box;
        move r to dst;
        place r box at dst;
    }
}
", "task": "move_box", "bindings": [{"param": "r", "id": "arm1"}, {"param": "box", "id": "box1"}, {"param": "src", "id": "shelf"}, {"param": "dst", "id": "table"}, {"param": "cell", "id": "cell"}]}
